/* eslint-disable eqeqeq */
import { Component, OnInit, SecurityContext } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { AngularEditorConfig } from '@kolkov/angular-editor';
import { CourseService } from '../../../../../data/service/course/course.service';
import { AddOrUpdateCourseModel, IAddOrUpdateCourseModel } from '../../../../../data/model/course/AddOrUpdateCourseModel';
import { GResponse } from '../../../../../core/common/GResponse';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { Router } from '@angular/router';
import { Urls } from '../../../../../core/common/Urls';
import { G } from '../../../../../core/common/G';

@Component({
  selector: 'app-add-course',
  templateUrl: './add-course.component.html',
  styleUrls: ['./add-course.component.scss']
})
export class AddCourseComponent implements OnInit {

  priceType = 'free';
  shortDescription: SafeHtml;
  description: SafeHtml;
  imageUrl: any;
  addCourseForm: FormGroup;
  courseCategoryIds: number[] = [];
  mechanicCategories = [];
  tuningCategories = [];
  designeCategories = [];

  course: IAddOrUpdateCourseModel;

  editorConfig: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات کوتاه...',
    translate: 'no',
    sanitize: true
  };

  editorConfig2: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات اصلی...',
    translate: 'no',
    sanitize: true
  };

  constructor(
    private courseService: CourseService,
    private fb: FormBuilder,
    public toastController: ToastController,
    private router: Router,
    public loadingController: LoadingController,
    private domSanitizer: DomSanitizer,
    public alertController: AlertController) { }

  ngOnInit(): void {

    this.addCourseForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(200)]],
      price: [0, [Validators.required, Validators.min(0), Validators.max(90000000000)]],
      offPrice: [0, [Validators.required, Validators.min(0), Validators.max(90000000000)]],
      imageUrl: ['http://localhost:4300/assets/images/in-progress.webp', [Validators.minLength(1), Validators.maxLength(1000000)]],
      imageNamePNG: ['http://localhost:4300/assets/images/in-progress.png', [Validators.minLength(1), Validators.maxLength(1000000)]],
      videoUrl: ['vflrB', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]],
      level: ['مقدماتی', [Validators.required, Validators.minLength(3), Validators.maxLength(100)]],
      shortDescriptionHtmlContent: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]],
      descriptionHtmlContent: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]]
    });

    this.mechanicCategories = [];
    this.tuningCategories = [];
    this.designeCategories = [];

    G.getCourseCategory().subscribe(
      res => {
        if (res != null) {
          if (res.length > 0) {
            res.forEach(c => {

              if (c.parentId == 1) {
                this.mechanicCategories.push(c);
              } else if (c.parentId == 2) {
                this.tuningCategories.push(c);
              } else if (c.parentId == 3) {
                this.designeCategories.push(c);
              }
            });
          }
        }
      }
    );
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  onPriceTypeChanged() {

    if (this.priceType === 'free') {
      this.addCourseForm.setValue({
        name: this.addCourseForm.value.name,
        level: this.addCourseForm.value.level,
        price: 0,
        offPrice: 0,
        imageUrl: this.addCourseForm.value.imageUrl,
        imageNamePNG: this.addCourseForm.value.imageNamePNG,
        videoUrl: this.addCourseForm.value.videoUrl,
        shortDescriptionHtmlContent: this.addCourseForm.value.shortDescriptionHtmlContent,
        descriptionHtmlContent: this.addCourseForm.value.descriptionHtmlContent
      });
    } else if (this.priceType === 'price') {
      this.addCourseForm.setValue({
        name: this.addCourseForm.value.name,
        level: this.addCourseForm.value.level,
        price: '',
        offPrice: 0,
        imageUrl: this.addCourseForm.value.imageUrl,
        imageNamePNG: this.addCourseForm.value.imageNamePNG,
        videoUrl: this.addCourseForm.value.videoUrl,
        shortDescriptionHtmlContent: this.addCourseForm.value.shortDescriptionHtmlContent,
        descriptionHtmlContent: this.addCourseForm.value.descriptionHtmlContent
      });
    } else if (this.priceType === 'offPrice') {
      this.addCourseForm.setValue({
        name: this.addCourseForm.value.name,
        level: this.addCourseForm.value.level,
        price: '',
        offPrice: '',
        imageUrl: this.addCourseForm.value.imageUrl,
        imageNamePNG: this.addCourseForm.value.imageNamePNG,
        videoUrl: this.addCourseForm.value.videoUrl,
        shortDescriptionHtmlContent: this.addCourseForm.value.shortDescriptionHtmlContent,
        descriptionHtmlContent: this.addCourseForm.value.descriptionHtmlContent
      });
    }
  }

  onCategoryChecked(courseCategoryId: number | string) {

    if (this.courseCategoryIds.find(c => c == courseCategoryId) == null) {

      this.courseCategoryIds.push(+courseCategoryId);
    } else {
      this.courseCategoryIds.splice(this.courseCategoryIds.findIndex(c => c == courseCategoryId), 1);
    }

  }

  onAdd() {

    if (this.addCourseForm.valid) {

      if (this.courseCategoryIds.length < 1) {

        SharedIonic.toast(this.toastController, 'گروهی انتخاب نشده است');
        return;
      }

      if (+this.addCourseForm.value.offPrice > +this.addCourseForm.value.price) {

        SharedIonic.toast(this.toastController, 'تخفیف بیشتر از قیمت اصلی است');
        return;
      }

      SharedIonic.loading(this.loadingController);

      // this.shortDescription = this.domSanitizer
      //   .sanitize(SecurityContext.HTML, this.addCourseForm.value.shortDescriptionHtmlContent);

      this.shortDescription = this.addCourseForm.value.shortDescriptionHtmlContent;

      this.description = this.domSanitizer
        .sanitize(SecurityContext.HTML, this.addCourseForm.value.descriptionHtmlContent);

      this.course =
        new AddOrUpdateCourseModel(
          null,
          this.addCourseForm.value.name,
          this.addCourseForm.value.price,
          this.addCourseForm.value.offPrice,
          this.shortDescription,
          this.description,
          this.addCourseForm.value.imageUrl,
          this.addCourseForm.value.imageNamePNG,
          this.addCourseForm.value.videoUrl,
          this.courseCategoryIds,
          false,
          '00:00',
          '',
          this.addCourseForm.value.level,
          false,
          1,
          20000,
          0,
          100
        );

      this.courseService.AddOrUpdateCourse(this.course).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.router.navigateByUrl(Urls.TeacherPanelUrl);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }
}
